using Backend.BDFolder;using Microsoft.EntityFrameworkCore;namespace Backend;public class TransportesRojasDbContext : DbContext{       public TransportesRojasDbContext(DbContextOptions<TransportesRojasDbContext> options)        : base(options) { }    public DbSet<Direccion> Direcciones => Set<Direccion>();    public DbSet<Sucursal> Sucursales => Set<Sucursal>();    public DbSet<Rol> Roles => Set<Rol>();    public DbSet<Puesto> Puestos => Set<Puesto>();    public DbSet<Permiso> Permisos => Set<Permiso>();    public DbSet<RolPermiso> RolPermisos => Set<RolPermiso>();    public DbSet<Usuario> Usuarios => Set<Usuario>();    public DbSet<UsuarioRol> UsuarioRoles => Set<UsuarioRol>();    public DbSet<UsuarioEstadoHistorial> UsuarioEstadosHistorial => Set<UsuarioEstadoHistorial>();    public DbSet<Empleado> Empleados => Set<Empleado>();    public DbSet<EmpleadoPuestoHistorial> EmpleadosPuestosHistorial => Set<EmpleadoPuestoHistorial>();    public DbSet<Cliente> Clientes => Set<Cliente>();    public DbSet<ClienteDireccion> ClientesDirecciones => Set<ClienteDireccion>();    public DbSet<Flotilla> Flotillas => Set<Flotilla>();    public DbSet<Unidad> Unidades => Set<Unidad>();    public DbSet<AsignacionFlotillaChofer> AsignacionesFlotillaChofer => Set<AsignacionFlotillaChofer>();    public DbSet<TipoMantenimiento> TiposMantenimiento => Set<TipoMantenimiento>();    public DbSet<AlertaMantenimiento> AlertasMantenimiento => Set<AlertaMantenimiento>();    public DbSet<Mantenimiento> Mantenimientos => Set<Mantenimiento>();    public DbSet<Envio> Envios => Set<Envio>();    public DbSet<EventoEnvio> EventosEnvio => Set<EventoEnvio>();    public DbSet<RecepcionPaquete> RecepcionesPaquete => Set<RecepcionPaquete>();    public DbSet<CitaRecoleccion> CitasRecoleccion => Set<CitaRecoleccion>();    public DbSet<Ruta> Rutas => Set<Ruta>();    public DbSet<RutaEnvio> RutasEnvios => Set<RutaEnvio>();    public DbSet<Entrega> Entregas => Set<Entrega>();    public DbSet<Devolucion> Devoluciones => Set<Devolucion>();    public DbSet<Reclamacion> Reclamaciones => Set<Reclamacion>();    public DbSet<Cancelacion> Cancelaciones => Set<Cancelacion>();    public DbSet<Alerta> Alertas => Set<Alerta>();    public DbSet<TelemetriaUnidad> Telemetrias => Set<TelemetriaUnidad>();    public DbSet<Incidencia> Incidencias => Set<Incidencia>();    public DbSet<Reprogramacion> Reprogramaciones => Set<Reprogramacion>();    public DbSet<Evaluacion> Evaluaciones => Set<Evaluacion>();    public DbSet<Queja> Quejas => Set<Queja>();    public DbSet<QuejaSeguimiento> QuejasSeguimiento => Set<QuejaSeguimiento>();    protected override void OnModelCreating(ModelBuilder b)    {        base.OnModelCreating(b);        foreach (var entityType in b.Model.GetEntityTypes())        {            var idProp = entityType.FindProperty("Id");            if (idProp != null && (idProp.ClrType == typeof(long) || idProp.ClrType == typeof(int)))                idProp.SetValueGenerationStrategy(                    Npgsql.EntityFrameworkCore.PostgreSQL.Metadata.NpgsqlValueGenerationStrategy.IdentityAlwaysColumn);        }        b.Entity<Direccion>(e =>        {            e.ToTable("direccion");            e.Property(x => x.Pais).HasDefaultValue("México");            e.Property(x => x.Metadata).HasColumnType("jsonb");            e.Property(x => x.Latitud).HasPrecision(10, 7);            e.Property(x => x.Longitud).HasPrecision(10, 7);        });        b.Entity<Sucursal>(e =>        {            e.ToTable("sucursal");            e.HasIndex(x => x.Codigo).IsUnique();            e.HasOne(x => x.Direccion).WithMany(d => d.Sucursales)                .HasForeignKey(x => x.DireccionId);        });        b.Entity<Rol>(e =>        {            e.ToTable("rol");            e.HasIndex(x => x.Nombre).IsUnique();        });        b.Entity<Puesto>(e =>        {            e.ToTable("puesto");            e.HasIndex(x => x.Nombre).IsUnique();        });        b.Entity<Permiso>(e =>        {            e.ToTable("permiso");            e.HasIndex(x => x.Codigo).IsUnique();            e.HasIndex(x => x.Modulo);        });        b.Entity<RolPermiso>(e =>        {            e.ToTable("rol_permiso");            e.HasKey(x => new { x.RolId, x.PermisoId });            e.HasOne(x => x.Rol).WithMany(r => r.RolPermisos).HasForeignKey(x => x.RolId);            e.HasOne(x => x.Permiso).WithMany(p => p.RolPermisos).HasForeignKey(x => x.PermisoId);        });        b.Entity<Usuario>(e =>        {            e.ToTable("usuario");            e.HasIndex(x => x.Email).IsUnique();            e.Property(x => x.TipoUsuario).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<TipoUsuario>(v));        });        b.Entity<UsuarioRol>(e =>        {            e.ToTable("usuario_rol");            e.HasKey(x => new { x.UsuarioId, x.RolId });        });        b.Entity<UsuarioEstadoHistorial>(e =>        {            e.ToTable("usuario_estado_historial");            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoUsuarioHist>(v));            e.HasOne(x => x.RegistradoPorEmpleado).WithMany()                .HasForeignKey(x => x.RegistradoPor);        });        b.Entity<Empleado>(e =>        {            e.ToTable("empleado");            e.HasIndex(x => x.UsuarioId).IsUnique();            e.HasIndex(x => x.SucursalId);        });        b.Entity<EmpleadoPuestoHistorial>(e =>        {            e.ToTable("empleado_puesto_historial");            e.HasIndex(x => x.EmpleadoId);        });        b.Entity<Cliente>(e =>        {            e.ToTable("cliente");            e.HasIndex(x => x.UsuarioId).IsUnique();            e.HasIndex(x => new { x.Nombre, x.ApellidoPaterno });        });        b.Entity<ClienteDireccion>(e =>        {            e.ToTable("cliente_direccion");            e.Property(x => x.Tipo).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<TipoClienteDireccion>(v));        });        b.Entity<Flotilla>(e =>        {            e.ToTable("flotilla");            e.HasIndex(x => x.Codigo).IsUnique();            e.HasOne(x => x.Supervisor).WithMany().HasForeignKey(x => x.SupervisorId);        });        b.Entity<Unidad>(e =>        {            e.ToTable("unidad");            e.HasIndex(x => x.Placas).IsUnique();            e.HasIndex(x => x.FlotillaId);            e.HasIndex(x => x.Estado);            e.Property(x => x.CapacidadKg).HasPrecision(10, 2);            e.Property(x => x.KmOdometroInicial).HasPrecision(10, 2);            e.Property(x => x.KmOdometroActual).HasPrecision(10, 2);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoUnidad>(v));        });        b.Entity<AsignacionFlotillaChofer>(e =>        {            e.ToTable("asignacion_flotilla_chofer");            e.HasIndex(x => x.FlotillaId);            e.HasIndex(x => x.ChoferId);            e.HasIndex(x => x.ChoferId).IsUnique()                .HasFilter("activo = TRUE")                .HasDatabaseName("uq_asig_chofer_activa");        });        b.Entity<TipoMantenimiento>(e =>        {            e.ToTable("tipo_mantenimiento");            e.HasIndex(x => x.Nombre).IsUnique();        });        b.Entity<AlertaMantenimiento>(e =>        {            e.ToTable("alerta_mantenimiento");            e.HasIndex(x => x.UnidadId);            e.HasIndex(x => x.Estado);            e.HasIndex(x => x.FechaAlerta);            e.Property(x => x.KmAlMomento).HasPrecision(10, 2);            e.Property(x => x.KmUmbral).HasPrecision(10, 2);            e.Property(x => x.KmUltimoMantenimiento).HasPrecision(10, 2);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoAlertaMant>(v));        });        b.Entity<Mantenimiento>(e =>        {            e.ToTable("mantenimiento");            e.HasIndex(x => x.UnidadId);            e.HasIndex(x => x.TipoMantenimientoId);            e.HasIndex(x => x.FechaRealizado);            e.Property(x => x.KmAlMomento).HasPrecision(10, 2);            e.Property(x => x.Costo).HasPrecision(12, 2);        });        b.Entity<Envio>(e =>        {            e.ToTable("envio");            e.HasIndex(x => x.Guia).IsUnique();            e.HasIndex(x => x.RemitenteId);            e.HasIndex(x => x.DestinatarioClienteId);            e.HasIndex(x => x.Estado);            e.HasIndex(x => x.SucursalRecepcionId);            e.HasIndex(x => x.SucursalDestinoId);            e.HasIndex(x => x.RequiereRecoleccion);            e.HasIndex(x => x.FechaCreacion);            e.Property(x => x.DireccionOrigenSnapshot).HasColumnType("jsonb");            e.Property(x => x.DireccionDestinoSnapshot).HasColumnType("jsonb");            e.Property(x => x.Metadata).HasColumnType("jsonb");            e.Property(x => x.PesoKg).HasPrecision(10, 2);            e.Property(x => x.LargoCm).HasPrecision(10, 2);            e.Property(x => x.AnchoCm).HasPrecision(10, 2);            e.Property(x => x.AltoCm).HasPrecision(10, 2);            e.Property(x => x.ValorDeclarado).HasPrecision(12, 2);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoEnvio>(v));            e.HasOne(x => x.Remitente).WithMany().HasForeignKey(x => x.RemitenteId);            e.HasOne(x => x.DestinatarioCliente).WithMany().HasForeignKey(x => x.DestinatarioClienteId);            e.HasOne(x => x.SucursalRecepcion).WithMany().HasForeignKey(x => x.SucursalRecepcionId);            e.HasOne(x => x.SucursalDestino).WithMany().HasForeignKey(x => x.SucursalDestinoId);            e.HasOne(x => x.DireccionDestino).WithMany().HasForeignKey(x => x.DireccionDestinoId);        });        b.Entity<EventoEnvio>(e =>        {            e.ToTable("evento_envio");            e.HasIndex(x => new { x.EnvioId, x.FechaEvento });            e.Property(x => x.Latitud).HasPrecision(10, 7);            e.Property(x => x.Longitud).HasPrecision(10, 7);        });        b.Entity<RecepcionPaquete>(e =>        {            e.ToTable("recepcion_paquete");            e.HasIndex(x => x.EnvioId).IsUnique();            e.Property(x => x.PesoVerificadoKg).HasPrecision(10, 2);            e.Property(x => x.LargoVerificadoCm).HasPrecision(10, 2);            e.Property(x => x.AnchoVerificadoCm).HasPrecision(10, 2);            e.Property(x => x.AltoVerificadoCm).HasPrecision(10, 2);        });        b.Entity<CitaRecoleccion>(e =>        {            e.ToTable("cita_recoleccion");            e.HasIndex(x => x.EnvioId);            e.HasIndex(x => x.Estado);            e.HasIndex(x => x.FechaHoraSolicitada);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoCitaRecoleccion>(v));        });        b.Entity<Ruta>(e =>        {            e.ToTable("ruta");            e.HasIndex(x => new { x.ChoferId, x.Fecha });            e.HasIndex(x => new { x.UnidadId, x.Fecha });            e.HasIndex(x => x.Estado);            e.Property(x => x.KmInicialOdometro).HasPrecision(10, 2);            e.Property(x => x.KmFinalOdometro).HasPrecision(10, 2);            e.Property(x => x.KmRecorridos).HasPrecision(10, 2);            e.Property(x => x.DistanciaEstimadaKm).HasPrecision(10, 2);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoRuta>(v));            e.Property(x => x.KmRecorridos)                .HasComputedColumnSql(                    "CASE WHEN km_final_odometro IS NOT NULL AND km_inicial_odometro IS NOT NULL " +                    "THEN km_final_odometro - km_inicial_odometro ELSE NULL END",                    stored: true);        });        b.Entity<RutaEnvio>(e =>        {            e.ToTable("ruta_envio");            e.HasIndex(x => new { x.RutaId, x.EnvioId }).IsUnique();            e.HasIndex(x => x.EnvioId);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoRutaEnvio>(v));        });        b.Entity<Entrega>(e =>        {            e.ToTable("entrega");            e.HasIndex(x => x.EnvioId).IsUnique();            e.HasIndex(x => x.ChoferId);            e.Property(x => x.Latitud).HasPrecision(10, 7);            e.Property(x => x.Longitud).HasPrecision(10, 7);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoEntrega>(v));        });        b.Entity<Devolucion>(e =>        {            e.ToTable("devolucion");            e.HasIndex(x => x.EnvioId);            e.HasIndex(x => x.Estado);            e.Property(x => x.OrigenSolicitud).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<OrigenSolicitudDevolucion>(v));            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoDevolucion>(v));        });        b.Entity<Reclamacion>(e =>        {            e.ToTable("reclamacion");            e.HasIndex(x => x.EnvioId);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoReclamacion>(v));        });        b.Entity<Cancelacion>(e =>        {            e.ToTable("cancelacion");            e.HasIndex(x => x.EnvioId);            e.Property(x => x.ActorTipo).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<ActorTipoCancelacion>(v));            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoCancelacion>(v));        });        b.Entity<Alerta>(e =>        {            e.ToTable("alerta");            e.HasIndex(x => x.Estado);            e.HasIndex(x => x.FlotillaId);            e.HasIndex(x => x.FechaAlerta);            e.Property(x => x.Latitud).HasPrecision(10, 7);            e.Property(x => x.Longitud).HasPrecision(10, 7);            e.Property(x => x.Tipo).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<TipoAlerta>(v));            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoAlerta>(v));        });        b.Entity<TelemetriaUnidad>(e =>        {            e.ToTable("telemetria_unidad");            e.HasIndex(x => new { x.UnidadId, x.FechaHora });            e.HasIndex(x => new { x.RutaId, x.FechaHora });            e.Property(x => x.Latitud).HasPrecision(10, 7);            e.Property(x => x.Longitud).HasPrecision(10, 7);        });        b.Entity<Incidencia>(e =>        {            e.ToTable("incidencia");            e.HasIndex(x => x.EnvioId);            e.HasIndex(x => x.Estado);            e.Property(x => x.Tipo).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<TipoIncidencia>(v));            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoIncidencia>(v));        });        b.Entity<Reprogramacion>(e =>        {            e.ToTable("reprogramacion");            e.HasIndex(x => x.EnvioId);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoReprogramacion>(v));        });        b.Entity<Evaluacion>(e =>        {            e.ToTable("evaluacion");            e.HasIndex(x => x.EnvioId).IsUnique();        });        b.Entity<Queja>(e =>        {            e.ToTable("queja");            e.HasIndex(x => x.Folio).IsUnique();            e.HasIndex(x => x.EnvioId);            e.HasIndex(x => x.Estado);            e.Property(x => x.Estado).HasConversion(                v => ConvertidorASnake.ToSnake(v),                v => ConvertidorASnake.FromSnake<EstadoQueja>(v));        });        b.Entity<QuejaSeguimiento>(e =>        {            e.ToTable("queja_seguimiento");            e.HasIndex(x => x.QuejaId);        });        b.Entity<UsuarioPermisoEfectivo>(e =>        {            e.HasNoKey();            e.ToView("usuario_permiso_efectivo");            e.Property(x => x.UsuarioId).HasColumnName("usuario_id");            e.Property(x => x.PermisoId).HasColumnName("permiso_id");            e.Property(x => x.PermisoCodigo).HasColumnName("permiso_codigo");            e.Property(x => x.PermisoModulo).HasColumnName("permiso_modulo");        });        foreach (var entity in b.Model.GetEntityTypes())        {            foreach (var prop in entity.GetProperties())            {                if (prop.GetColumnName() == prop.Name)                    prop.SetColumnName(ToSnakeCase(prop.Name));            }        }    }    private static string ToSnakeCase(string name)    {        var sb = new System.Text.StringBuilder();        for (int i = 0; i < name.Length; i++)        {            var c = name[i];            if (char.IsUpper(c) && i > 0) sb.Append('_');            sb.Append(char.ToLowerInvariant(c));        }        return sb.ToString();    }    private void UpdateTimestamps()    {        var now = DateTimeOffset.UtcNow;        foreach (var entry in ChangeTracker.Entries())        {            if (entry.State == EntityState.Added)            {                var createdAtProp = entry.Properties.FirstOrDefault(p => p.Metadata.Name == "CreatedAt");                if (createdAtProp != null && (createdAtProp.CurrentValue == null || Equals(createdAtProp.CurrentValue, default(DateTimeOffset))))                {                    createdAtProp.CurrentValue = now;                }                var updatedAtProp = entry.Properties.FirstOrDefault(p => p.Metadata.Name == "UpdatedAt");                if (updatedAtProp != null && (updatedAtProp.CurrentValue == null || Equals(updatedAtProp.CurrentValue, default(DateTimeOffset))))                {                    updatedAtProp.CurrentValue = now;                }            }            else if (entry.State == EntityState.Modified)            {                var updatedAtProp = entry.Properties.FirstOrDefault(p => p.Metadata.Name == "UpdatedAt");                if (updatedAtProp != null)                {                    updatedAtProp.CurrentValue = now;                }                var createdAtProp = entry.Properties.FirstOrDefault(p => p.Metadata.Name == "CreatedAt");                if (createdAtProp != null)                {                    createdAtProp.IsModified = false;                }            }        }    }    public override int SaveChanges() => SaveChanges(true);    public override int SaveChanges(bool acceptAllChangesOnSuccess)    {        UpdateTimestamps();        return base.SaveChanges(acceptAllChangesOnSuccess);    }    public override Task<int> SaveChangesAsync(CancellationToken ct = default) => SaveChangesAsync(true, ct);    public override Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken ct = default)    {        UpdateTimestamps();        return base.SaveChangesAsync(acceptAllChangesOnSuccess, ct);    }}public class UsuarioPermisoEfectivo{    public long UsuarioId { get; set; }    public long PermisoId { get; set; }    public string PermisoCodigo { get; set; } = null!;    public string PermisoModulo { get; set; } = null!;}